-- Insert Quiz Questions for Lesson: What Is a CRM?

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 9 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 9 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'what-is-crm' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson what-is-crm not found in module 9';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What does CRM stand for?', 
    '["Customer Revenue Management","Customer Relationship Management","Company Resource Management","Contact Record Management"]'::jsonb,
    'Customer Relationship Management',
    'CRM stands for Customer Relationship Management. It is a system for managing interactions with current and potential customers.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the difference between a contact list and a CRM?', 
    '["There is no difference","A contact list stores information; a CRM helps you act on that information","Contact lists are more expensive","CRMs do not store contact information"]'::jsonb,
    'A contact list stores information; a CRM helps you act on that information',
    'A contact list is passive storage. A CRM actively helps you track interactions, automate follow-up, and manage the customer journey.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the key rule of a working CRM?', 
    '["Store as much data as possible","Every lead should have a clear next step","Never delete anything","Only track paying customers"]'::jsonb,
    'Every lead should have a clear next step',
    'The key rule is that every lead should have a clear next step. A CRM is an action system, not just a storage system.', 
