-- Insert Quiz Questions for Lesson: The Eight-Part LeadProspectrr System

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 9 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 9 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'eight-part-system' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson eight-part-system not found in module 9';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What are the eight parts of the LeadProspectrr system?', 
    '["Email, Phone, Text, Chat, Social, Video, Mail, In-person","Attract, Capture, Organize, Communicate, Track, Follow Up, Sell, Report","Prospecting, Pitching, Closing, Delivering, Billing, Supporting, Retaining, Growing","Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, Sunday, Holiday"]'::jsonb,
    'Attract, Capture, Organize, Communicate, Track, Follow Up, Sell, Report',
    'The eight parts are: Attract, Capture, Organize, Communicate, Track, Follow Up, Sell, and Report. This covers the complete customer journey.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Which part involves using Opportunities and Pipelines?', 
    '["Communicate","Track","Attract","Report"]'::jsonb,
    'Track',
    'The Track phase uses Opportunities and Pipelines to monitor possible sales, stages, values, and statuses.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the purpose of the Follow Up phase?', 
    '["To find new customers","To use Workflows for repeatable actions like emails, texts, and reminders","To create invoices","To delete old contacts"]'::jsonb,
    'To use Workflows for repeatable actions like emails, texts, and reminders',
    'The Follow Up phase uses Workflows to automate repeatable actions like sending emails, texts, reminders, and creating tasks.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


