-- Insert Quiz Questions for Lesson: Contacts — The Center of the CRM

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 9 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 9 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'contacts-center' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson contacts-center not found in module 9';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is at the center of the LeadProspectrr CRM?', 
    '["The dashboard","The contact record","The settings menu","The reports section"]'::jsonb,
    'The contact record',
    'The contact record is the center of the CRM. All activity, communication, appointments, and opportunities connect back to the contact.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What information can a contact record include?', 
    '["Only name and email","Name, email, phone, company, source, tags, custom fields, notes, tasks, appointments, conversations, opportunities, documents, and payments","Just the phone number","Only tags"]'::jsonb,
    'Name, email, phone, company, source, tags, custom fields, notes, tasks, appointments, conversations, opportunities, documents, and payments',
    'A complete contact record includes basic information, organization tags and fields, and full activity history including notes, tasks, appointments, conversations, opportunities, documents, and payments.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why is the contact record important?', 
    '["It is required by law","All activity and history connects to it, creating a complete picture of the relationship","It takes up storage space","It slows down the system"]'::jsonb,
    'All activity and history connects to it, creating a complete picture of the relationship',
    'The contact record is important because it connects all activity, communication, and history in one place, giving you a complete picture of each relationship.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


