-- Insert Quiz Questions for Lesson: Opportunities and Pipelines

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 9 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 9 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'opportunities-pipelines-overview' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson opportunities-pipelines-overview not found in module 9';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the difference between a contact and an opportunity?', 
    '["There is no difference","A contact is the person; an opportunity is a possible sale connected to that person","Contacts are free; opportunities cost money","Opportunities are not stored in LeadProspectrr"]'::jsonb,
    'A contact is the person; an opportunity is a possible sale connected to that person',
    'A contact represents the person or business. An opportunity represents a possible sale connected to that contact. One contact can have multiple opportunities.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is a pipeline?', 
    '["A type of email","A visual representation of your sales process","A type of contact","A payment method"]'::jsonb,
    'A visual representation of your sales process',
    'A pipeline visually represents your sales process with stages like New Lead, Contacted, Appointment Booked, Proposal Sent, and Won/Lost.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What can pipelines help you see?', 
    '["Only the weather forecast","Who needs follow-up, who has booked, who received proposals, deal values, and won/lost sales","Only email addresses","Nothing useful"]'::jsonb,
    'Who needs follow-up, who has booked, who received proposals, deal values, and won/lost sales',
    'Pipelines help you see who needs follow-up, who has booked appointments, who received proposals, which deals have gone quiet, the value of open opportunities, and which sales were won or lost.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


