-- Insert Quiz Questions for Lesson: Workflows and Follow-Up

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 9 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 9 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'workflows-followup' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson workflows-followup not found in module 9';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is a workflow?', 
    '["A type of contact","A set of automatic actions triggered by an event","A payment method","A report type"]'::jsonb,
    'A set of automatic actions triggered by an event',
    'A workflow is a series of automatic actions triggered by an event, such as form submission, tag application, or appointment booking.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What can workflow actions include?', 
    '["Only sending emails","Adding tags, sending emails and texts, creating opportunities, assigning contacts, creating tasks, waiting, and checking for replies","Only deleting contacts","Nothing, workflows do nothing"]'::jsonb,
    'Adding tags, sending emails and texts, creating opportunities, assigning contacts, creating tasks, waiting, and checking for replies',
    'Workflows can perform many actions: add tags, send emails and texts, create opportunities, assign contacts, create tasks, wait, check for replies, and much more.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the key idea about workflows?', 
    '["Automate everything without thinking","Automate a clear process. If the manual process does not make sense, automating it will not fix it.","Never use workflows","Workflows replace all human interaction"]'::jsonb,
    'Automate a clear process. If the manual process does not make sense, automating it will not fix it.',
    'The key is to automate a clear, working process. Map out the manual process first, then automate it. Automation amplifies good processes and bad processes alike.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


