-- Insert Quiz Questions for Lesson: Payments, Documents, and Reputation

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 9 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 9 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'payments-documents-reputation' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson payments-documents-reputation not found in module 9';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What payment tools might LeadProspectrr include?', 
    '["Only cash payments","Invoices, payment links, products, order forms, and subscriptions","Only checks","No payment tools"]'::jsonb,
    'Invoices, payment links, products, order forms, and subscriptions',
    'LeadProspectrr can include various payment tools: invoices, payment links, products, order forms, and subscriptions, all connected to contact records.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is a simple review process?', 
    '["Never ask for reviews","Service completed → workflow sends review request → customer follows link → business monitors response → relationship continues","Buy fake reviews","Only ask unhappy customers"]'::jsonb,
    'Service completed → workflow sends review request → customer follows link → business monitors response → relationship continues',
    'A good review process uses workflows to automatically request reviews after service completion, making it easy for customers to leave feedback.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why are documents connected to contacts important?', 
    '["They take up storage space","They provide easy access to proposals, contracts, and agreements in one place","They are not important","They slow down the system"]'::jsonb,
    'They provide easy access to proposals, contracts, and agreements in one place',
    'When documents are connected to contacts, you have easy access to all proposals, contracts, and agreements in one place, creating a complete record of the relationship.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


