-- Insert Quiz Questions for Lesson: Dashboards and Reporting

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 9 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 9 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'dashboards-reporting' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson dashboards-reporting not found in module 9';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What can LeadProspectrr report on?', 
    '["Nothing","Contacts, conversations, appointments, opportunities, pipeline value, conversion activity, payments, and revenue","Only email addresses","Only the weather"]'::jsonb,
    'Contacts, conversations, appointments, opportunities, pipeline value, conversion activity, payments, and revenue',
    'LeadProspectrr can report on many areas: contacts, conversations, calls, appointments, opportunities, pipeline value, conversion activity, payments, and revenue.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the key idea about dashboards?', 
    '["They replace the need for a sales process","They show what is happening but do not replace a clear sales and follow-up process","They are not useful","They automatically fix problems"]'::jsonb,
    'They show what is happening but do not replace a clear sales and follow-up process',
    'Dashboards show what is happening in your business, but they complement—do not replace—your sales and follow-up processes. You still need clear processes.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What questions should reports help answer?', 
    '["Only the CEO''s salary","How many new leads, where they came from, appointments booked, opportunities open, deals stuck, pipeline value, sales won, and revenue collected","Only employee birthdays","What to have for lunch"]'::jsonb,
    'How many new leads, where they came from, appointments booked, opportunities open, deals stuck, pipeline value, sales won, and revenue collected',
    'Reports should answer key business questions: lead volume, sources, appointments, opportunities, pipeline value, conversions, and revenue.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


